steps.css:
body {
  max-width: 380px;
  margin: 35px auto;
  padding: 25px;
  font-family: Arial, sans-serif;
  text-align: center;
  color: #243150;
  background: #eff4ff;
  border: 2px solid #b9caec;
  border-radius: 18px;
}
h1 { color: #374e8a; }
input {
  width: 75px;
  padding: 9px;
  border: 2px solid #b9caec;
  border-radius: 7px;
  font-size: 1rem;
  text-align: center;
}
button {
  padding: 10px 15px;
  color: white;
  background: #526db4;
  border: 0;
  border-radius: 7px;
  cursor: pointer;
}
button:hover { background: #3c5193; }
#ausgabe {
  min-height: 2em;
  color: #a97008;
  font-size: 2rem;
  overflow-wrap: anywhere;
}
#meldung { min-height: 1.5em; }

